/**
 * Race replay dataset (`public/replay/<year>/<sessionKey>.json`, schema `apex-f1/race-replay@1`), generated by tools/openf1-replay from
 * OpenF1. All times are ms from the replay start (`startUtc`). Everything is recorded source data; positions are recorded samples thinned
 * to `positionStepMs` and delta-encoded on disk. `parseReplay` validates and decodes it (a trust boundary: the file comes from outside).
 */
export const REPLAY_SCHEMA = "apex-f1/race-replay@1";

/** [lap number, start (ms), lap time (s), sector 1, 2, 3 (s)]; times null when not published. */
export type ReplayLap = [number, number, number | null, (number | null)?, (number | null)?, (number | null)?];

export interface ReplayDriver {
  number: number;
  acronym: string | null;
  fullName: string | null;
  team: string | null;
  teamColour: string | null;
  /** Recorded positions, decoded: strictly increasing t (ms), OpenF1 location x/y. */
  positions: { t: number[]; x: number[]; y: number[] };
  /** In lap order. Sector times are present in files exported since sector support (older files have 3 entries). */
  laps: ReplayLap[];
  /** Published gaps: to the leader and to the car ahead (s), or whole laps down. */
  intervals: { t: number[]; gap: (number | null)[]; interval: (number | null)[]; lapsDown: (number | null)[] };
  /** Tyre stints as published, in order (empty in files exported before stint support). */
  stints: ReplayStint[];
}

/** A tyre stint: compound as published (e.g. "SOFT"; null if not published), laps it covers, tyre age in laps at its start. */
export interface ReplayStint {
  stint: number;
  compound: string | null;
  lapStart: number | null;
  lapEnd: number | null;
  ageAtStart: number | null;
}

export interface RaceControlMessage {
  t: number;
  category: string | null;
  flag: string | null;
  scope: string | null;
  message: string;
  lap: number | null;
  number: number | null;
}

/** Weather station readings (about one a minute), as published: °C, %, hPa, m/s, degrees; rain 0/1. Null = not published. */
export interface ReplayWeather {
  t: number[];
  air: (number | null)[];
  track: (number | null)[];
  humidity: (number | null)[];
  pressure: (number | null)[];
  rain: (number | null)[];
  windSpeed: (number | null)[];
  windDir: (number | null)[];
}

export interface ReplayDataset {
  season: number;
  meetingKey: number;
  sessionKey: number;
  eventName: string;
  circuitShortName: string | null;
  date: string;
  coordinateSystem: string;
  startUtc: string;
  lightsOutMs: number;
  durationMs: number;
  positionStepMs: number;
  source: { name: string; url: string; fetchedOn: string; note: string };
  drivers: ReplayDriver[];
  /** Official running-order changes: [t, car number, position], in time order. */
  order: [number, number, number][];
  pits: { t: number; number: number; lap: number | null; laneS: number | null; stopS: number | null }[];
  raceControl: RaceControlMessage[];
  /** On-track passes as published by OpenF1: [t, overtaking car, overtaken car, position gained] (empty in older exports). */
  overtakes: [number, number, number, number | null][];
  /** Absent in files exported before weather support. */
  weather: ReplayWeather | null;
  /** What validation removed (reported in the UI, never hidden). */
  dropped: { positionSamples: number; orderRows: number; drivers: number };
}

export interface ReplayIndexEntry {
  sessionKey: number;
  meetingKey: number;
  eventName: string;
  circuitShortName: string | null;
  date: string;
  durationMs: number;
  drivers: number;
  laps: number;
  /** Median share of the race window with recorded positions (0..1); below 1 when the source stopped publishing positions. */
  positionCoverage?: number;
}

type Result<T> = { ok: true; value: T } | { ok: false; error: string };
const isObj = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);
const fin = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
const numOrNull = (v: unknown): number | null => (fin(v) ? v : null);
const strOrNull = (v: unknown): string | null => (typeof v === "string" && v.length > 0 ? v : null);

/** Decodes delta arrays and drops anything that cannot be a recorded sample: non-finite values, duplicate or backwards timestamps. */
export function decodePositions(raw: unknown): { t: number[]; x: number[]; y: number[]; dropped: number } {
  const out = { t: [] as number[], x: [] as number[], y: [] as number[], dropped: 0 };
  if (!isObj(raw) || !Array.isArray(raw.dt) || !Array.isArray(raw.dx) || !Array.isArray(raw.dy)) return out;
  const n = Math.min(raw.dt.length, raw.dx.length, raw.dy.length);
  out.dropped += Math.max(raw.dt.length, raw.dx.length, raw.dy.length) - n;
  let [t, x, y] = [0, 0, 0];
  for (let i = 0; i < n; i++) {
    const [a, b, c] = [raw.dt[i], raw.dx[i], raw.dy[i]];
    if (!fin(a) || !fin(b) || !fin(c)) {
      out.dropped += n - i; // a corrupt delta would shift every later sample: stop decoding this driver here
      break;
    }
    [t, x, y] = i === 0 ? [a, b, c] : [t + a, x + b, y + c];
    if (out.t.length && t <= out.t[out.t.length - 1]) {
      out.dropped++;
      continue;
    }
    out.t.push(t);
    out.x.push(x);
    out.y.push(y);
  }
  return out;
}

export function parseReplay(raw: unknown): Result<ReplayDataset> {
  if (!isObj(raw)) return { ok: false, error: "not an object" };
  if (raw.schema !== REPLAY_SCHEMA) return { ok: false, error: `unsupported schema ${String(raw.schema)}` };
  for (const k of ["season", "meetingKey", "sessionKey"] as const) if (!Number.isInteger(raw[k])) return { ok: false, error: `${k} must be an integer` };
  if (!fin(raw.durationMs) || raw.durationMs <= 0) return { ok: false, error: "durationMs must be positive" };
  if (!fin(raw.lightsOutMs) || !fin(raw.positionStepMs)) return { ok: false, error: "needs lightsOutMs and positionStepMs" };
  if (typeof raw.startUtc !== "string" || !Number.isFinite(Date.parse(raw.startUtc))) return { ok: false, error: "startUtc must be an ISO time" };
  if (typeof raw.coordinateSystem !== "string" || typeof raw.eventName !== "string") return { ok: false, error: "needs coordinateSystem and eventName" };
  if (!Array.isArray(raw.drivers) || !Array.isArray(raw.order) || !Array.isArray(raw.pits) || !Array.isArray(raw.raceControl)) return { ok: false, error: "needs drivers, order, pits, raceControl" };

  const dropped = { positionSamples: 0, orderRows: 0, drivers: 0 };
  const drivers: ReplayDriver[] = [];
  const seen = new Set<number>();
  for (const d of raw.drivers) {
    if (!isObj(d) || !Number.isInteger(d.number) || seen.has(d.number as number)) {
      dropped.drivers++; // inconsistent or duplicated identity: never merged or guessed
      continue;
    }
    seen.add(d.number as number);
    const positions = decodePositions(d.positions);
    dropped.positionSamples += positions.dropped;
    const laps = (Array.isArray(d.laps) ? d.laps : [])
      .filter((l): l is ReplayLap => Array.isArray(l) && l.length >= 3 && Number.isInteger(l[0]) && fin(l[1]) && l.slice(2).every((v: unknown) => v === null || fin(v)))
      .sort((a, b) => a[0] - b[0]);
    const iv = isObj(d.intervals) ? d.intervals : {};
    const ivT = Array.isArray(iv.t) ? iv.t : [];
    const keep = ivT.map((t, i) => (fin(t) ? i : -1)).filter((i) => i >= 0);
    const col = (k: string) => (Array.isArray(iv[k]) ? (iv[k] as unknown[]) : []);
    drivers.push({
      number: d.number as number,
      acronym: strOrNull(d.acronym),
      fullName: strOrNull(d.fullName),
      team: strOrNull(d.team),
      teamColour: typeof d.teamColour === "string" && /^#[0-9a-f]{6}$/i.test(d.teamColour) ? d.teamColour : null,
      positions: { t: positions.t, x: positions.x, y: positions.y },
      laps,
      intervals: { t: keep.map((i) => ivT[i] as number), gap: keep.map((i) => numOrNull(col("gap")[i])), interval: keep.map((i) => numOrNull(col("interval")[i])), lapsDown: keep.map((i) => numOrNull(col("lapsDown")[i])) },
      stints: (Array.isArray(d.stints) ? d.stints : [])
        .filter((x): x is unknown[] => Array.isArray(x) && Number.isInteger(x[0]))
        .map((x) => ({ stint: x[0] as number, compound: typeof x[1] === "string" ? x[1].toUpperCase() : null, lapStart: numOrNull(x[2]), lapEnd: numOrNull(x[3]), ageAtStart: numOrNull(x[4]) }))
        .sort((a, b) => a.stint - b.stint),
    });
  }
  if (drivers.length === 0) return { ok: false, error: "no valid drivers" };
  const known = new Set(drivers.map((d) => d.number));
  const order = (raw.order as unknown[]).filter((r): r is [number, number, number] => {
    const ok = Array.isArray(r) && fin(r[0]) && known.has(r[1] as number) && Number.isInteger(r[2]) && (r[2] as number) > 0;
    if (!ok) dropped.orderRows++;
    return ok;
  });
  order.sort((a, b) => a[0] - b[0]);
  const pits = (raw.pits as unknown[])
    .filter((p): p is Record<string, unknown> => isObj(p) && fin(p.t) && known.has(p.number as number))
    .map((p) => ({ t: p.t as number, number: p.number as number, lap: numOrNull(p.lap), laneS: numOrNull(p.laneS), stopS: numOrNull(p.stopS) }))
    .sort((a, b) => a.t - b.t);
  const raceControl = (raw.raceControl as unknown[])
    .filter((r): r is Record<string, unknown> => isObj(r) && fin(r.t) && typeof r.message === "string")
    .map((r) => ({ t: r.t as number, category: strOrNull(r.category), flag: strOrNull(r.flag), scope: strOrNull(r.scope), message: r.message as string, lap: numOrNull(r.lap), number: numOrNull(r.number) }))
    .sort((a, b) => a.t - b.t);
  const overtakes = (Array.isArray(raw.overtakes) ? (raw.overtakes as unknown[]) : [])
    .filter((o): o is unknown[] => Array.isArray(o) && fin(o[0]) && known.has(o[1] as number) && known.has(o[2] as number))
    .map((o) => [o[0], o[1], o[2], numOrNull(o[3])] as [number, number, number, number | null])
    .sort((a, b) => a[0] - b[0]);
  const src = isObj(raw.source) ? raw.source : {};
  return {
    ok: true,
    value: {
      season: raw.season as number,
      meetingKey: raw.meetingKey as number,
      sessionKey: raw.sessionKey as number,
      eventName: raw.eventName,
      circuitShortName: strOrNull(raw.circuitShortName),
      date: typeof raw.date === "string" ? raw.date : "",
      coordinateSystem: raw.coordinateSystem,
      startUtc: raw.startUtc,
      lightsOutMs: raw.lightsOutMs,
      durationMs: raw.durationMs,
      positionStepMs: raw.positionStepMs,
      source: { name: String(src.name ?? "OpenF1"), url: String(src.url ?? ""), fetchedOn: String(src.fetchedOn ?? ""), note: String(src.note ?? "") },
      drivers,
      order,
      pits,
      raceControl,
      overtakes,
      weather: parseWeather(raw.weather),
      dropped,
    },
  };
}

/** Weather columns aligned to valid, increasing times; anything malformed is dropped (and with no valid rows there is no weather). */
function parseWeather(raw: unknown): ReplayWeather | null {
  if (!isObj(raw) || !Array.isArray(raw.t)) return null;
  const cols = ["air", "track", "humidity", "pressure", "rain", "windSpeed", "windDir"] as const;
  const out: ReplayWeather = { t: [], air: [], track: [], humidity: [], pressure: [], rain: [], windSpeed: [], windDir: [] };
  raw.t.forEach((t, i) => {
    if (!fin(t) || (out.t.length && t <= out.t[out.t.length - 1])) return;
    out.t.push(t);
    for (const c of cols) out[c].push(numOrNull(Array.isArray(raw[c]) ? (raw[c] as unknown[])[i] : null));
  });
  return out.t.length ? out : null;
}

export function parseReplayIndex(raw: unknown): Result<ReplayIndexEntry[]> {
  if (!isObj(raw) || raw.schema !== "apex-f1/race-replay-index@1" || !Array.isArray(raw.sessions)) return { ok: false, error: "not a race-replay index" };
  const out: ReplayIndexEntry[] = [];
  for (const s of raw.sessions) {
    if (!isObj(s) || !Number.isInteger(s.sessionKey) || typeof s.eventName !== "string" || !fin(s.durationMs)) return { ok: false, error: "invalid index entry" };
    out.push(s as unknown as ReplayIndexEntry);
  }
  return { ok: true, value: out };
}
